--
-- Estrutura para tabela `apoios_artistas`
--

CREATE TABLE `apoios_artistas` (
  `id` bigint(20) UNSIGNED NOT NULL,
  `referencia` char(36) NOT NULL,
  `artista_id` int(11) NOT NULL,
  `apoiador_usuario_id` int(11) NOT NULL,
  `valor` decimal(10,2) NOT NULL,
  `status` varchar(24) NOT NULL DEFAULT 'pending',
  `status_detalhe` varchar(100) DEFAULT NULL,
  `mp_preference_id` varchar(100) DEFAULT NULL,
  `mp_payment_id` varchar(40) DEFAULT NULL,
  `criado_em` timestamp NOT NULL DEFAULT current_timestamp(),
  `atualizado_em` timestamp NOT NULL DEFAULT current_timestamp() ON UPDATE current_timestamp()
) ;

-- --------------------------------------------------------

--
-- Estrutura para tabela `artistas`
--

CREATE TABLE `artistas` (
  `id` int(11) NOT NULL,
  `nome` varchar(150) NOT NULL,
  `genero_id` int(11) DEFAULT NULL,
  `pais` varchar(60) DEFAULT NULL,
  `biografia` text DEFAULT NULL,
  `foto_url` varchar(255) DEFAULT NULL,
  `criado_em` timestamp NOT NULL DEFAULT current_timestamp(),
  `spotify_url` varchar(255) DEFAULT NULL
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_general_ci;

