--
-- Estrutura stand-in para view `vw_media_musicas`
-- (Veja abaixo para a visão atual)
--
CREATE TABLE `vw_media_musicas` (
`musica_id` int(11)
,`musica` varchar(150)
,`album` varchar(150)
,`artista` varchar(150)
,`genero` varchar(60)
,`media_nota` decimal(6,2)
,`total_avaliacoes` bigint(21)
);

-- --------------------------------------------------------

--
-- Estrutura para view `vw_media_albuns`
--
DROP TABLE IF EXISTS `vw_media_albuns`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_media_albuns`  AS SELECT `al`.`id` AS `album_id`, `al`.`titulo` AS `album`, `ar`.`nome` AS `artista`, `g`.`nome` AS `genero`, round(avg(`aa`.`nota`),2) AS `media_nota`, count(`aa`.`id`) AS `total_avaliacoes` FROM (((`albuns` `al` join `artistas` `ar` on(`ar`.`id` = `al`.`artista_id`)) left join `generos` `g` on(`g`.`id` = `al`.`genero_id`)) left join `avaliacoes_albuns` `aa` on(`aa`.`album_id` = `al`.`id`)) GROUP BY `al`.`id`, `al`.`titulo`, `ar`.`nome`, `g`.`nome` ;

-- --------------------------------------------------------

--
-- Estrutura para view `vw_media_musicas`
--
DROP TABLE IF EXISTS `vw_media_musicas`;

CREATE ALGORITHM=UNDEFINED DEFINER=`root`@`localhost` SQL SECURITY DEFINER VIEW `vw_media_musicas`  AS SELECT `m`.`id` AS `musica_id`, `m`.`titulo` AS `musica`, `al`.`titulo` AS `album`, `ar`.`nome` AS `artista`, `g`.`nome` AS `genero`, round(avg(`am`.`nota`),2) AS `media_nota`, count(`am`.`id`) AS `total_avaliacoes` FROM ((((`musicas` `m` join `albuns` `al` on(`al`.`id` = `m`.`album_id`)) join `artistas` `ar` on(`ar`.`id` = `al`.`artista_id`)) left join `generos` `g` on(`g`.`id` = `m`.`genero_id`)) left join `avaliacoes_musicas` `am` on(`am`.`musica_id` = `m`.`id`)) GROUP BY `m`.`id`, `m`.`titulo`, `al`.`titulo`, `ar`.`nome`, `g`.`nome` ;

